// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.matflow;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class MatWorkflowDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        SnapshotComparer comparer = new SnapshotComparer();

        // SNAPSHOT 1 (like first heap dump): early in the run.
        simulateLoad(5_000);
        long snap1 = NotificationRegistry.liveListenerCount();
        comparer.record("dump-1 (early)", snap1);

        // more steady load over "hours"...
        simulateLoad(45_000);
        long snap2 = NotificationRegistry.liveListenerCount();
        comparer.record("dump-2 (hours later)", snap2);

        // STEP: compare the two snapshots — which class grew? (slow-leak detection)
        comparer.diff("dump-1 (early)", "dump-2 (hours later)");

        // STEP: "Path to GC Roots" — name the retainer that pins the memory.
        log.warning(() -> "Path to GC Roots: NotificationRegistry.LISTENERS (static field) "
                + "retains every listener → THIS is the leak (a GC root keeps them alive)");
        log.info(() -> "Right question: not 'what is big?' but 'what RETAINS this and why not freed?'");

        // FIX: deregister listeners so the static registry stops retaining them.
        NotificationRegistry.clear();
        log.info(() -> "after fix (deregister/bound): live listeners = "
                + NotificationRegistry.liveListenerCount());
    }

    // Each "request" registers a listener but (buggily) never deregisters it.
    private static void simulateLoad(int requests) {
        for (int i = 0; i < requests; i++) {
            NotificationRegistry.register(payload -> { /* send SMS/email */ });
        }
    }
}

// ─── Would be in NotificationRegistry.java (STATIC retainer = GC root leak) ───
interface Listener { void onEvent(String payload); }

class NotificationRegistry {
    // STATIC field → a GC root. Anything here is NEVER collected until removed.
    private static final java.util.List<Listener> LISTENERS = new java.util.ArrayList<>();
    static void register(Listener l) { LISTENERS.add(l); } // never removed = leak
    static long liveListenerCount() { return LISTENERS.size(); }
    static void clear() { LISTENERS.clear(); } // the fix: release the references
}

// ─── Would be in SnapshotComparer.java (mimics MAT two-dump diff) ───
class SnapshotComparer {
    private static final Logger log = Logger.getLogger("BankLog");
    private final java.util.Map<String, Long> snapshots = new java.util.LinkedHashMap<>();

    void record(String name, long listenerCount) {
        snapshots.put(name, listenerCount);
        log.info(() -> "[" + name + "] Listener instances retained = " + listenerCount);
    }

    void diff(String first, String second) {
        long a = snapshots.get(first), b = snapshots.get(second);
        log.warning(() -> "DIFF " + first + " → " + second + ": Listener grew by "
                + (b - a) + " instances (steady upward growth = the leaking class)");
    }
}
